INSERT INTO `api_logs` (`id`, `method`, `endpoint`, `status_code`, `ip_address`, `user_agent`, `client_type`, `response_time_ms`, `request_payload`, `created_at`, `updated_at`) VALUES ('787', 'POST', '/admin/products', '302', '127.0.0.1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.0.0 Safari/537.36', 'Web Control Panel (Admin)', '56', '{\"name\":\"TP-LINK 8-Port Gigabit Desktop Switch - TL-SG108\",\"sku\":\"HDW-002\",\"brand\":\"TP-LINK\",\"category_id\":\"1\",\"price\":\"330000\",\"stock\":\"12\",\"unit\":\"unit\",\"description\":\"TP-Link TL-SG108 8-Port 10/100/1000Mbps Desktop Switch\\r\\nGaransi Resmi Dari TP-Link Selama 3 Tahun\\r\\nKey Features :\\r\\n- 8-Port 10/100/1000Mbps Desktop Switch\\r\\n- 8 port RJ45 10/100/1000Mbps Auto-Negotiation, Mendukung Auto MDI / MDIX\\r\\n- IEEE 802.3x flow control menyediakan transfer data yang dapat diandalkan\\r\\n- Casing baja, didesain untuk pemasangan desktop / pada dinding\\r\\n- Mendukung fungsi QoS (IEEE 802.1p)\\r\\n- Plug and play, tidak ada konfigurasi yang diperlukan\\r\\nHardware Features :\\r\\n- Standards and Protocols IEEE 802.3 / 802.3u / 802.3ab/ 802.3x /802.1p\\r\\n- Interface 8 10/100/1000Mbps Ports, Auto-Negotiation, Auto-MDI/MDIX\\r\\n- Fan Quantity Fanless\\r\\n- Power Consumption Maximum: 3.97 (220V/50Hz)\\r\\n- External Power Supply External Power Adapter (Output: 9VDC / 0.6A)\\r\\n- Buffer Size 1.5Mb\\r\\n- LED Indicator System Power\\r\\n- Link, Speed and activity indicators per port built into each RJ-45 port\\r\\n- Dimensions ( W x D x H ) 6.2 x 4.0 x 1.0 in. (158 x 101 x 25 mm)\\r\\nPerformance :\\r\\n- Packet Forwarding Rate 11.9Mpps\\r\\n- MAC Address Table 4K\\r\\n- Packet Buffer Memory 1.5Mb\\r\\n- Jumbo Frame 15KB\\r\\nSoftware Features :\\r\\n- Advanced Features Green Technology,saving power up to 82%\\r\\n- 802.3X Flow Control\\r\\n- 802.1p/DSCP QoS1\\r\\n- IGMP Snooping1\\r\\n- Transfer Method Store and Forward\\r\\nPackage Contents :\\r\\n- 8-Port 10/100/1000Mbps Desktop Switch\\r\\n- Power Adapter\\r\\n- Installation Guide\",\"is_active\":\"1\",\"stay\":\"1\",\"image\":{}}', '2026-11-11 14:19:23', '2026-11-11 14:19:23');
