INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `type`, `brand`, `unit`, `short_description`, `description`, `price`, `stock`, `image_path`, `is_active`, `created_at`, `updated_at`) VALUES ('1', '1', 'HDW-001', 'Mikrotik RB450Gx4', 'mikrotik-rb450gx4', 'hardware', 'MIKROTIK', 'unit', 'Routerboard RB450Gx4 (716MHz Quad Core CPU, 1 GB DDR RAM, 512MB NAND Storage) dengan RouterOS (Level 5) dalam kemasan kotak indoor yang ringkas, 5 (lima) buah port gigabit 10/100/1000, dan slot mikro-...', 'Routerboard RB450Gx4 (716MHz Quad Core CPU, 1 GB DDR RAM, 512MB NAND Storage) dengan RouterOS (Level 5) dalam kemasan kotak indoor yang ringkas, 5 (lima) buah port gigabit 10/100/1000, dan slot mikro-SD. Tidak bisa dipasangkan wireless card. Sudah termasuk 1 buah adaptor 24 Volt.', '1800000.00', '6', 'products/UhwjnYv2SHxkbukn7oKWDXGQ6oJkssythSXpyRBh.jpg', '1', '2026-11-11 14:06:49', '2026-11-11 14:06:49');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `type`, `brand`, `unit`, `short_description`, `description`, `price`, `stock`, `image_path`, `is_active`, `created_at`, `updated_at`) VALUES ('2', '1', 'HDW-002', 'TP-LINK 8-Port Gigabit Desktop Switch - TL-SG108', 'tp-link-8-port-gigabit-desktop-switch-tl-sg108', 'hardware', 'TP-LINK', 'unit', 'TP-Link TL-SG108 8-Port 10/100/1000Mbps Desktop Switch\r\nGaransi Resmi Dari TP-Link Selama 3 Tahun\r\nKey Features :\r\n- 8-Port 10/100/1000Mbps Desktop Switch\r\n- 8 port RJ45 10/100/1000Mbps Auto-Negotiati...', 'TP-Link TL-SG108 8-Port 10/100/1000Mbps Desktop Switch\r\nGaransi Resmi Dari TP-Link Selama 3 Tahun\r\nKey Features :\r\n- 8-Port 10/100/1000Mbps Desktop Switch\r\n- 8 port RJ45 10/100/1000Mbps Auto-Negotiation, Mendukung Auto MDI / MDIX\r\n- IEEE 802.3x flow control menyediakan transfer data yang dapat diandalkan\r\n- Casing baja, didesain untuk pemasangan desktop / pada dinding\r\n- Mendukung fungsi QoS (IEEE 802.1p)\r\n- Plug and play, tidak ada konfigurasi yang diperlukan\r\nHardware Features :\r\n- Standards and Protocols IEEE 802.3 / 802.3u / 802.3ab/ 802.3x /802.1p\r\n- Interface 8 10/100/1000Mbps Ports, Auto-Negotiation, Auto-MDI/MDIX\r\n- Fan Quantity Fanless\r\n- Power Consumption Maximum: 3.97 (220V/50Hz)\r\n- External Power Supply External Power Adapter (Output: 9VDC / 0.6A)\r\n- Buffer Size 1.5Mb\r\n- LED Indicator System Power\r\n- Link, Speed and activity indicators per port built into each RJ-45 port\r\n- Dimensions ( W x D x H ) 6.2 x 4.0 x 1.0 in. (158 x 101 x 25 mm)\r\nPerformance :\r\n- Packet Forwarding Rate 11.9Mpps\r\n- MAC Address Table 4K\r\n- Packet Buffer Memory 1.5Mb\r\n- Jumbo Frame 15KB\r\nSoftware Features :\r\n- Advanced Features Green Technology,saving power up to 82%\r\n- 802.3X Flow Control\r\n- 802.1p/DSCP QoS1\r\n- IGMP Snooping1\r\n- Transfer Method Store and Forward\r\nPackage Contents :\r\n- 8-Port 10/100/1000Mbps Desktop Switch\r\n- Power Adapter\r\n- Installation Guide', '330000.00', '11', 'products/3K4xGVJsww2ZCFQC3AtzQbYIOY3DYfVyut1TZNZI.jpg', '1', '2026-11-11 14:19:23', '2026-11-11 14:32:04');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `type`, `brand`, `unit`, `short_description`, `description`, `price`, `stock`, `image_path`, `is_active`, `created_at`, `updated_at`) VALUES ('3', '1', 'HDW-003', 'TP-LINK TL-WR 840N 300MBps Wireless Router Multifungsi Extender', 'tp-link-tl-wr-840n-300mbps-wireless-router-multifungsi-extender', 'hardware', 'TP-LINK', 'unit', 'TL-WR840N yang kita jual merupakan versi terbaru, produk ini memiliki multifungsi yaitu routher wireless, extender dan acess point.\r\n\r\n\r\nTL-WR840N 300MBps Wireless Router\r\nVERSI Terbaru : 7.20\r\n\r\n\r\n”K...', 'TL-WR840N yang kita jual merupakan versi terbaru, produk ini memiliki multifungsi yaitu routher wireless, extender dan acess point.\r\n\r\n\r\nTL-WR840N 300MBps Wireless Router\r\nVERSI Terbaru : 7.20\r\n\r\n\r\n”Key Features :\r\nWR840N：\r\n- Dapat Digunakan Menjadi Access Point, Wireless Router, Range Extender,\r\nDan WISP (Menghubungkan WIFI dengan WIFI tanpa merubah IP)\r\n-300 Mbps wireless transmission rate ideal for both bandwidth sensitive tasks and basic work\r\n-Supports 4 modes: Router, Range Extender, Access Point and WISP modes\r\n-Parental Controls manage when and how connected devices can access the internet\r\n-IPTV supports IGMP Proxy/Snooping, Bridge and Tag VLAN to optimize IPTV streaming\r\n-Compatible with IPv6 (Internet Protocol version 6)\r\n-Guest Network provides separate access for guests while securing the home network\r\n\r\n\r\nFungsi Produk :\r\nTL-WR840N adalah gabungan kabel / jaringan nirkabel yang dirancang khusus untuk kebutuhan jaringan kecil rumahan. TL-WR840N menciptakan kinerja nirkabel yang luar biasa dan canggih, sehingga ideal untuk streaming video HD, VoIP dan game online. Dan juga, Tombol setup (WPS) Wi-Fi Protected pada bagian luar ramping dan modis memastikan enkripsi WPA2, mencegah jaringan dari intrusi luar.\r\nHardware Features:\r\n- Interface : 4 10/100Mbps LAN PORTS, 1 10/100Mbps WAN PORT\r\n- Button : WPS/RESET Button\r\n- Antenna : 2 Antennas\r\n- External Power Supply : 9VDC / 0.6A\r\n- Wireless Standards : IEEE 802.11n, IEEE 802.11g, IEEE 802.11b\r\n- Dimensions ( W x D x H ) : 7.2 x 5.0 x 1.4in.(182 x 128 x 35 mm)\r\n- Wireless Functions : Enable/Disable Wireless Radio, WDS Bridge, WMM, Wireless Statistics\r\n- Wireless Security : 64/128-bit WEP, WPA / WPA2,WPA-PSK / WPA2-PSK\r\n- Quality of Service : WMM, Bandwidth Control\r\n- WAN Type : Dynamic IP/Static IP/PPPoE/ PPTP/L2TP\r\n- Management : Access Control, Local Management, Remote Management\r\n- DHCP : Server, Client, DHCP Client List, Address Reservation\r\n- Port Forwarding : Virtual Server,Port Triggering, UPnP, DMZ\r\n- Dynamic DNS : DynDns, Comexe, NO-IP\r\n- VPN Pass-Through : PPTP, L2TP, IPSec (ESP Head)\r\n- Access Control : Parental Control, Local Management Control, Host List, Access Schedule, Rule Management\r\n- Firewall Security : DoS, SPI Firewall, IP Address Filter/MAC Address Filter/Domain Filter, IP and MAC Address Binding\r\n- Protocols : Support IPv4 and IPv6\r\n- Guest Network : 2.4GHz Guest Network x1\r\n- Certification : CE, RoHS\r\n\r\n\r\n\r\nPackage Contents :\r\n- Wi-Fi Router TL-WR840N\r\n-Power Adapter\r\n-RJ45 Ethernet Cable\r\n- Quick Installation Guide', '170000.00', '7', 'products/5BbwUsQEAf4SK2YKgFycosYmVD11YSX2eEEuReM3.jpg', '1', '2026-11-11 14:45:09', '2026-11-11 14:45:09');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `type`, `brand`, `unit`, `short_description`, `description`, `price`, `stock`, `image_path`, `is_active`, `created_at`, `updated_at`) VALUES ('4', '3', 'SRV-001', 'Audit Keamanan Jaringan', 'audit-keamanan-jaringan', 'service', NULL, 'jasa', 'Layanan Audit Keamanan Jaringan adalah jasa asesmen menyeluruh terhadap infrastruktur jaringan komputer (LAN, WAN, Wireless, dan perimeter jaringan) untuk mengidentifikasi celah kerentanan (vulnerabil...', 'Layanan Audit Keamanan Jaringan adalah jasa asesmen menyeluruh terhadap infrastruktur jaringan komputer (LAN, WAN, Wireless, dan perimeter jaringan) untuk mengidentifikasi celah kerentanan (vulnerabilities), salah konfigurasi (misconfiguration), serta potensi ancaman siber sebelum dieksploitasi oleh pihak yang tidak bertanggung jawab.\r\n\r\nAudit ini memberikan visibilitas penuh terhadap postur keamanan jaringan Anda, memastikan integritas data, ketersediaan operasional, serta kepatuhan terhadap standar keamanan industri.', '2500000.00', NULL, NULL, '1', '2026-11-11 14:53:09', '2026-11-11 14:53:09');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `type`, `brand`, `unit`, `short_description`, `description`, `price`, `stock`, `image_path`, `is_active`, `created_at`, `updated_at`) VALUES ('5', '2', 'LIC-001', 'Microsoft  365 1 Years', 'microsoft-365-1-years', 'software', 'Microsoft', 'Lisensi', 'Microsoft 365 Business Standard adalah paket langganan produktivitas berbasis cloud resmi dari Microsoft yang dirancang untuk mendukung operasional bisnis, instansi, dan profesional. Lisensi ini menca...', 'Microsoft 365 Business Standard adalah paket langganan produktivitas berbasis cloud resmi dari Microsoft yang dirancang untuk mendukung operasional bisnis, instansi, dan profesional. Lisensi ini mencakup aplikasi Office versi desktop terinstal penuh, email bisnis kustom, penyimpanan cloud terpusat, serta fitur kolaborasi kerja jarak jauh.', '700000.00', '3', 'products/QBBUD6AhsiI4TYCOpTp1eW72Ih7qE6fU5C3shqv7.png', '1', '2026-11-11 14:57:17', '2026-11-11 14:57:58');
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `slug`, `type`, `brand`, `unit`, `short_description`, `description`, `price`, `stock`, `image_path`, `is_active`, `created_at`, `updated_at`) VALUES ('6', '2', 'LIC-002', 'Windows 11 Pro', 'windows-11-pro', 'software', 'Windows', 'Lisensi', 'Sistem operasi resmi Microsoft Windows 11 Pro dirancang untuk kebutuhan komersial, profesional IT, dan workstation bisnis modern. Menghadirkan antarmuka modern yang responsif, perlindungan data berbas...', 'Sistem operasi resmi Microsoft Windows 11 Pro dirancang untuk kebutuhan komersial, profesional IT, dan workstation bisnis modern. Menghadirkan antarmuka modern yang responsif, perlindungan data berbasis perangkat keras, integrasi cloud, serta kontrol penuh terhadap manajemen perangkat lokal maupun domain jaringan.', '800000.00', '15', 'products/nOIdBYbdXEmgkzM70j0j7KF88sWAHvXsPacPhfVz.webp', '1', '2026-11-11 15:10:40', '2026-11-11 15:13:47');
